local SetHammerMaker = {}
local PRODUCTS = {
    iron_sethammer = { name = "Železni nastavitveno kladivo", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni nastavitveno kladivo za kovace." },
    bronze_sethammer = { name = "Bronast nastavitveno kladivo", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast nastavitveno kladivo za kovace." },
    silver_sethammer = { name = "Srebrn nastavitveno kladivo", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn nastavitveno kladivo za kovace." },
    gilded_sethammer = { name = "Pozlačen nastavitveno kladivo", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen nastavitveno kladivo za kovace." },
    jewel_set_sethammer = { name = "Draguljast nastavitveno kladivo", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast nastavitveno kladivo za kovace." },
    royal_sovereign_sethammer = { name = "Kraljevski suveren nastavitveno kladivo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren nastavitveno kladivo z biseri za krono." },
}
local BUILDINGS = {
    sethammer_workshop = { name = "Sethammer delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    sethammer_house = { name = "Sethammer hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_sethammer_atelier = { name = "Mojstrski sethammer atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_sethammer_palace = { name = "Suverena sethammer palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
SetHammerMaker.ironStock=18; SetHammerMaker.bronzeStock=14; SetHammerMaker.woodStock=10; SetHammerMaker.leatherStock=8; SetHammerMaker.silverStock=8; SetHammerMaker.goldStock=6; SetHammerMaker.jewelStock=4; SetHammerMaker.pearlStock=4
SetHammerMaker.productStock = {}; SetHammerMaker.buildings = {}; SetHammerMaker.maker = nil; SetHammerMaker.activeMaking = {}; SetHammerMaker.totalProducts = 0; SetHammerMaker.dayTimer = 0
function SetHammerMaker.init() SetHammerMaker.ironStock=18; SetHammerMaker.bronzeStock=14; SetHammerMaker.woodStock=10; SetHammerMaker.leatherStock=8; SetHammerMaker.silverStock=8; SetHammerMaker.goldStock=6; SetHammerMaker.jewelStock=4; SetHammerMaker.pearlStock=4; SetHammerMaker.productStock={}; SetHammerMaker.buildings={}; SetHammerMaker.maker=nil; SetHammerMaker.activeMaking={}; SetHammerMaker.totalProducts=0; SetHammerMaker.dayTimer=0; print("[SetHammerMaker] Royal Set Hammer Maker System initialized (6 products, 4 buildings)") end
function SetHammerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SetHammerMaker.maker={name=n or ("Nastavljalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Nastavljalec najet: %s (spretnost: %d)",SetHammerMaker.maker.name,s),"success") end; return true end
function SetHammerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SetHammerMaker.build(id) local ok,e=SetHammerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SetHammerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SetHammerMaker.getQualityBonus() local b=0; for _,bd in ipairs(SetHammerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SetHammerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SetHammerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SetHammerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SetHammerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SetHammerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SetHammerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SetHammerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SetHammerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SetHammerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SetHammerMaker.buildings==0 then return false,"Potrebna nastavitvena delavnica" end; if not SetHammerMaker.maker then return false,"Potreben nastavljalec" end; return true end
function SetHammerMaker.make(pt,qty) qty=qty or 1; local ok,e=SetHammerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SetHammerMaker.ironStock=SetHammerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SetHammerMaker.bronzeStock=SetHammerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SetHammerMaker.woodStock=SetHammerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SetHammerMaker.leatherStock=SetHammerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SetHammerMaker.silverStock=SetHammerMaker.silverStock-d.silverCost*qty end; if d.goldCost then SetHammerMaker.goldStock=SetHammerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SetHammerMaker.jewelStock=SetHammerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SetHammerMaker.pearlStock=SetHammerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SetHammerMaker.maker then t=math.max(1,t-math.floor(SetHammerMaker.maker.skill/13)) end; table.insert(SetHammerMaker.activeMaking,{id="sethammer_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SetHammerMaker.completeMaking(m) local q=1.0+(SetHammerMaker.getQualityBonus()/100); if SetHammerMaker.maker then q=q+(SetHammerMaker.maker.skill/140) end; q=math.min(2.5,q); SetHammerMaker.productStock[m.productType]=(SetHammerMaker.productStock[m.productType] or 0)+m.quantity; SetHammerMaker.totalProducts=SetHammerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SetHammerMaker.maker then SetHammerMaker.maker.itemsMade=SetHammerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SetHammerMaker.maker.skill=math.min(100,SetHammerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Nastavljalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sethammer.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SetHammerMaker.update(dt) if not _G.state then return end; SetHammerMaker.dayTimer=SetHammerMaker.dayTimer+dt; if SetHammerMaker.dayTimer>=30 then SetHammerMaker.dayTimer=0; for i=#SetHammerMaker.activeMaking,1,-1 do local m=SetHammerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SetHammerMaker.completeMaking(m); table.remove(SetHammerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SetHammerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SetHammerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SetHammerMaker.getStats() return {ironStock=SetHammerMaker.ironStock,bronzeStock=SetHammerMaker.bronzeStock,woodStock=SetHammerMaker.woodStock,leatherStock=SetHammerMaker.leatherStock,silverStock=SetHammerMaker.silverStock,goldStock=SetHammerMaker.goldStock,jewelStock=SetHammerMaker.jewelStock,pearlStock=SetHammerMaker.pearlStock,productStock=SetHammerMaker.productStock,numBuildings=#SetHammerMaker.buildings,hasMaker=SetHammerMaker.maker~=nil,makerName=SetHammerMaker.maker and SetHammerMaker.maker.name or "—",makerSkill=SetHammerMaker.maker and SetHammerMaker.maker.skill or 0,activeMaking=#SetHammerMaker.activeMaking,totalProducts=SetHammerMaker.totalProducts} end
return SetHammerMaker
